//! app-benchmarks — Phase 48 static-crate entry point.
//!
//! Generated by scripts/migrate_app_to_static.py. The `#[path]` mod
//! declarations let the cargo build reach the existing modules/ and
//! resources/ files without moving them — both the dylib path
//! (yeti-compiler flat-src copy) and the static path (this crate)
//! share source during the migration window. Slice 5 retires the
//! dylib path; a follow-up commit then moves modules/ → src/ and
//! drops the `#[path]` attrs.


use yeti_sdk::extensions::{RegistrationContext, Service};
use yeti_sdk::prelude::*;

// ── Shared helper modules ───────────────────────────────────────────
#[path = "../modules/bin_load_blob.rs"]
mod bin_load_blob;
#[path = "../modules/bin_load_graphql.rs"]
mod bin_load_graphql;
#[path = "../modules/bin_load_realtime.rs"]
mod bin_load_realtime;
#[path = "../modules/bin_load_rest.rs"]
mod bin_load_rest;
#[path = "../modules/bin_load_vector.rs"]
mod bin_load_vector;
#[path = "../modules/cli.rs"]
mod cli;
#[path = "../modules/client.rs"]
mod client;
#[path = "../modules/common.rs"]
mod common;
#[path = "../modules/metrics.rs"]
mod metrics;
#[path = "../modules/reporter.rs"]
mod reporter;
#[path = "../modules/runner.rs"]
mod runner;

// ── Resources ───────────────────────────────────────────────────────
#[path = "../resources/benchmark_runner.rs"]
mod benchmark_runner;
#[path = "../resources/best_results.rs"]
mod best_results;
#[path = "../resources/history.rs"]
mod history;

/// Factory invoked by the customer deployment binary.
pub fn service() -> Box<dyn Service> {
    Box::new(AppBenchmarksService)
}

struct AppBenchmarksService;

impl Service for AppBenchmarksService {
    fn id(&self) -> &'static str {
        "app-benchmarks"
    }

    fn name(&self) -> &'static str {
        "Yeti Benchmarks"
    }

    fn is_extension(&self) -> bool {
        false
    }

    fn config_yaml(&self) -> Option<&'static str> {
        Some(include_str!("../config.yaml"))
    }

    fn schemas(&self) -> Vec<&'static str> {
        vec![include_str!("../schema.graphql")]
    }

    fn resources(&self, ctx: &mut RegistrationContext) -> yeti_sdk::error::Result<()> {
        ctx.add_resource(Box::new(benchmark_runner::BenchmarkRunner));
        ctx.add_resource(Box::new(best_results::BestResults));
        ctx.add_resource(Box::new(history::History));
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn factory_returns_configured_service() {
        let svc = service();
        assert_eq!(svc.id(), "app-benchmarks");
    }

    #[test]
    fn factory_satisfies_server_builder_bounds() {
        fn assert_factory_bounds<F>(_: F)
        where
            F: Fn() -> Box<dyn Service> + Send + Sync + 'static,
        {
        }
        assert_factory_bounds(service);
    }
}
